        r.perHost = C.PER_HOST_PPS;
        succ = Math.min(D.FETCHERS, r.hosts) * C.PER_HOST_PPS * C.FRAME_S;
        r.fRefused = 0;
        r.fBlocked = 0;
        r.blockedFrac = 0;
